	// For our purposes, we need to detect when stdin is tty (interactive) vs pipe (non-tty).
	// The standard way: using syscall, but we can approximate by checking if stdin is a character device.

	// Use os.Stdin.Stat()
	fi, err := f.Stat()
	if err != nil {
