		lines, _ = readLines(f, cfg.Null)
		f.Close()
	} else {
		if isTerminal(os.Stdin) {
			fmt.Fprintf(os.Stderr, "Error: failed to setup input source: you must supply something to work with via filename or stdin\n")
			os.Exit(1)
		}
		lines, _ = readLines(os.Stdin, cfg.Null)
	}

	if cfg.BufferSize != nil {
		bs := *cfg.BufferSize
		if bs < 0 {
			bs = 0
		}
		if bs > 0 && len(lines) > bs {
			lines = lines[len(lines)-bs:]
		}
	}

	if cfg.Exit0 && len(lines) == 0 {
		os.Exit(1)
	}

	if cfg.SelectAll {
		if cfg.Query == "" {
			if cfg.PrintQuery {
				fmt.Fprintln(os.Stdout, cfg.Query)
			}
			for _, l := range lines {
				os.Stdout.Write([]byte(l.Result))
				os.Stdout.Write([]byte("\n"))
			}
			os.Exit(0)
		} else {
			attemptScreenInit()
			filtered := filterLines(lines, cfg.Query, cfg.InitialFilter)
			if cfg.PrintQuery {
				fmt.Fprintln(os.Stdout, cfg.Query)
			}
			for _, l := range filtered {
				os.Stdout.Write([]byte(l.Result))
				os.Stdout.Write([]byte("\n"))
			}
			os.Exit(0)
		}
	}

	if cfg.Select1 {
		if len(lines) == 1 {
			if cfg.PrintQuery {
				fmt.Fprintln(os.Stdout, cfg.Query)
			}
			os.Stdout.Write([]byte(lines[0].Result))
			os.Stdout.Write([]byte("\n"))
			os.Exit(0)
		}
		if cfg.Query != "" {
			filtered := filterLines(lines, cfg.Query, cfg.InitialFilter)
			if len(filtered) == 1 {
				attemptScreenInit()
				if cfg.PrintQuery {
					fmt.Fprintln(os.Stdout, cfg.Query)
				}
				os.Stdout.Write([]byte(filtered[0].Result))
				os.Stdout.Write([]byte("\n"))
				os.Exit(0)
			}
		}
		attemptScreenInit()
		runUI(cfg, lines)
		return
	}

	if cfg.Exit0 {
		attemptScreenInit()
		runUI(cfg, lines)
		return
	}

	attemptScreenInit()
	runUI(cfg, lines)
}

type Line struct {
	Display string
	Result  string
}

func readLines(r io.Reader, useNull bool) ([]Line, error) {
	var lines []Line
	br := bufio.NewReader(r)
	for {
		lineBytes, err := br.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return lines, err
		}
		if len(lineBytes) == 0 && err == io.EOF {
			break
		}
		if len(lineBytes) > 0 && lineBytes[len(lineBytes)-1] == '\n' {
			lineBytes = lineBytes[:len(lineBytes)-1]
		}
		s := string(lineBytes)
		var display, result string
		if useNull {
			idx := strings.IndexByte(s, '\x00')
			if idx >= 0 {
				display = s[:idx]
				result = s[idx+1:]
			} else {
				display = s
				result = s
			}
		} else {
			display = s
			result = s
		}
		lines = append(lines, Line{Display: display, Result: result})
		if err == io.EOF {
			break
		}
	}
	return lines, nil
}

type QueryTerm struct {
	Text     string
	Negative bool
}

func parseQueryTerms(q string) []QueryTerm {
	q = strings.TrimSpace(q)
	if q == "" {
		return nil
	}
	parts := strings.Fields(q)
	var terms []QueryTerm
	for _, p := range parts {
		if p == "-" {
			terms = append(terms, QueryTerm{Text: "-", Negative: false})
			continue
		}
		if strings.HasPrefix(p, `\-`) {
			terms = append(terms, QueryTerm{Text: p[1:], Negative: false})
			continue
		}
		if strings.HasPrefix(p, "-") && len(p) > 1 {
			terms = append(terms, QueryTerm{Text: p[1:], Negative: true})
		} else {
			terms = append(terms, QueryTerm{Text: p, Negative: false})
		}
	}
	return terms
}

func filterLines(lines []Line, query, filterName string) []Line {
	terms := parseQueryTerms(query)
	var res []Line
	for _, l := range lines {
		if matchesLine(l.Display, terms, filterName) {
			res = append(res, l)
		}
	}
	return res
}

func matchesLine(display string, terms []QueryTerm, filterName string) bool {
	isSmartCase := filterName == "SmartCase"
	smartSensitive := false
	if isSmartCase {
		for _, t := range terms {
			if strings.ToLower(t.Text) != t.Text {
				smartSensitive = true
				break
			}
		}
	}
	for _, term := range terms {
		text := term.Text
		if text == "" {
			continue
		}
		var contains bool
		switch filterName {
		case "CaseSensitive":
			contains = strings.Contains(display, text)
		case "SmartCase":
			if smartSensitive {
				contains = strings.Contains(display, text)
			} else {
				contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
			}
		case "Regexp":
			contains = strings.Contains(display, text)
		case "IRegexp":
			contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
		case "Fuzzy":
			contains = fuzzyMatch(display, text)
		default:
			contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
		}
		if term.Negative {
			if contains {
				return false
			}
		} else {
			if !contains {
				return false
			}
		}
	}
	return true
}

func fuzzyMatch(s, pattern string) bool {
	sLow := strings.ToLower(s)
	pLow := strings.ToLower(pattern)
	j := 0
	for i := 0; i < len(sLow) && j < len(pLow); i++ {
		if sLow[i] == pLow[j] {
			j++
		}
	}
	return j == len(pLow)
}

func attemptScreenInit() {
	term := os.Getenv("TERM")
	if term == "" {
		fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set\n")
		os.Exit(1)
	}
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: failed to initialize tcell screen: open /dev/tty: no such device or address\n")
		os.Exit(1)
	}
	f.Close()
}

