func parseHeight(s string) error {
	if s == "" {
		return nil
	}
	if strings.HasSuffix(s, "%") {
		numStr := strings.TrimSuffix(s, "%")
		n, err := strconv.Atoi(numStr)
		if err != nil {
			return err
		}
		if n <= 0 || n > 100 {
			return fmt.Errorf("invalid")
		}
		return nil
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return err
	}
	if n < 0 {
		return fmt.Errorf("invalid")
	}
	return nil
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	if (fi.Mode() & os.ModeCharDevice) != 0 {
		return true
	}
	return false
}

func parseArgs(args []string) (*Config, error) {
	cfg := &Config{}
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			if cfg.File == "" {
				cfg.File = "--"
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			nameVal := strings.SplitN(arg[2:], "=", 2)
			name := nameVal[0]
			var val *string
			if len(nameVal) == 2 {
				v := nameVal[1]
				val = &v
			}
			switch name {
			case "help":
				cfg.Help = true
				i++
				continue
			case "version":
				cfg.Version = true
				i++
				continue
			case "null":
				cfg.Null = true
				i++
				continue
			case "select-1":
				cfg.Select1 = true
				i++
				continue
			case "exit-0":
				cfg.Exit0 = true
				i++
				continue
			case "select-all":
				cfg.SelectAll = true
				i++
				continue
			case "print-query":
				cfg.PrintQuery = true
				i++
				continue
			case "ansi":
				cfg.Ansi = true
				i++
				continue
			case "query":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--query")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Query = v
				i++
				continue
			case "rcfile":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--rcfile")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Rcfile = v
				i++
				continue
			case "buffer-size", "b":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--buffer-size")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					printInvalidIntArg("-b, --buffer-size", v)
					return nil, fmt.Errorf("invalid int")
				}
				cfg.BufferSize = &n
				i++
				continue
			case "initial-index":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--initial-index")
