				}
				n, err := strconv.Atoi(v)
				if err != nil {
					printInvalidIntArg("--initial-index", v)
					return nil, fmt.Errorf("invalid int")
				}
				cfg.InitialIndex = &n
				i++
				continue
			case "initial-filter":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--initial-filter")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.InitialFilter = v
				i++
				continue
			case "prompt":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--prompt")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Prompt = v
