				} else {
					if i+1 >= len(args) {
						printMissingArg("--layout")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Layout = v
				i++
				continue
			case "on-cancel":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--on-cancel")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.OnCancel = v
				i++
				continue
			case "selection-prefix":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--selection-prefix")
						return nil, fmt.Errorf("missing")
