						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Height = v
				i++
				continue
			default:
				fmt.Fprintf(os.Stderr, "unknown flag `%s'\n\n", name)
				fmt.Fprint(os.Stderr, usage)
				fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: unknown flag `%s'\n", name)
