type Line struct {
	Display string
	Result  string
}

func readLines(r io.Reader, useNull bool) ([]Line, error) {
	var lines []Line
	br := bufio.NewReader(r)
	for {
		lineBytes, err := br.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return lines, err
		}
		if len(lineBytes) == 0 && err == io.EOF {
			break
		}
		if len(lineBytes) > 0 && lineBytes[len(lineBytes)-1] == '\n' {
			lineBytes = lineBytes[:len(lineBytes)-1]
		}
		s := string(lineBytes)
		var display, result string
		if useNull {
			idx := strings.IndexByte(s, '\x00')
			if idx >= 0 {
				display = s[:idx]
				result = s[idx+1:]
			} else {
				display = s
				result = s
			}
		} else {
			display = s
			result = s
		}
		lines = append(lines, Line{Display: display, Result: result})
		if err == io.EOF {
			break
		}
	}
	return lines, nil
}

type QueryTerm struct {
	Text     string
	Negative bool
}

func parseQueryTerms(q string) []QueryTerm {
	q = strings.TrimSpace(q)
	if q == "" {
		return nil
	}
	parts := strings.Fields(q)
	var terms []QueryTerm
	for _, p := range parts {
		if p == "-" {
			terms = append(terms, QueryTerm{Text: "-", Negative: false})
			continue
		}
		if strings.HasPrefix(p, `\-`) {
			terms = append(terms, QueryTerm{Text: p[1:], Negative: false})
			continue
		}
		if strings.HasPrefix(p, "-") && len(p) > 1 {
			terms = append(terms, QueryTerm{Text: p[1:], Negative: true})
		} else {
			terms = append(terms, QueryTerm{Text: p, Negative: false})
		}
	}
	return terms
}

func filterLines(lines []Line, query, filterName string) []Line {
	terms := parseQueryTerms(query)
	var res []Line
	for _, l := range lines {
		if matchesLine(l.Display, terms, filterName) {
			res = append(res, l)
		}
	}
	return res
}

func matchesLine(display string, terms []QueryTerm, filterName string) bool {
	isSmartCase := filterName == "SmartCase"
	smartSensitive := false
	if isSmartCase {
		for _, t := range terms {
			if strings.ToLower(t.Text) != t.Text {
				smartSensitive = true
				break
			}
		}
	}
	for _, term := range terms {
		text := term.Text
		if text == "" {
			continue
		}
		var contains bool
		switch filterName {
		case "CaseSensitive":
			contains = strings.Contains(display, text)
		case "SmartCase":
			if smartSensitive {
				contains = strings.Contains(display, text)
			} else {
				contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
			}
		case "Regexp":
			contains = strings.Contains(display, text)
		case "IRegexp":
			contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
		case "Fuzzy":
			contains = fuzzyMatch(display, text)
		default:
			contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
		}
		if term.Negative {
			if contains {
				return false
			}
		} else {
			if !contains {
				return false
			}
		}
	}
	return true
}

func fuzzyMatch(s, pattern string) bool {
	sLow := strings.ToLower(s)
	pLow := strings.ToLower(pattern)
	j := 0
	for i := 0; i < len(sLow) && j < len(pLow); i++ {
		if sLow[i] == pLow[j] {
			j++
		}
	}
	return j == len(pLow)
}

