func parseHeight(s string) error {
	if s == "" {
		return nil
	}
	if strings.HasSuffix(s, "%") {
		numStr := strings.TrimSuffix(s, "%")
		n, err := strconv.Atoi(numStr)
		if err != nil {
			return err
		}
		if n <= 0 || n > 100 {
			return fmt.Errorf("invalid")
		}
		return nil
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return err
	}
	if n < 0 {
		return fmt.Errorf("invalid")
	}
	return nil
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	if (fi.Mode() & os.ModeCharDevice) != 0 {
		return true
	}
	return false
}

