		}
	}
	return terms
}

func filterLines(lines []Line, query, filterName string) []Line {
	terms := parseQueryTerms(query)
	var res []Line
	for _, l := range lines {
		if matchesLine(l.Display, terms, filterName) {
			res = append(res, l)
		}
	}
	return res
}

func matchesLine(display string, terms []QueryTerm, filterName string) bool {
	isSmartCase := filterName == "SmartCase"
	smartSensitive := false
	if isSmartCase {
		for _, t := range terms {
			if strings.ToLower(t.Text) != t.Text {
				smartSensitive = true
				break
			}
		}
	}
	for _, term := range terms {
		text := term.Text
		if text == "" {
			continue
		}
		var contains bool
		switch filterName {
		case "CaseSensitive":
			contains = strings.Contains(display, text)
		case "SmartCase":
			if smartSensitive {
				contains = strings.Contains(display, text)
			} else {
				contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
			}
		case "Regexp":
			contains = strings.Contains(display, text)
		case "IRegexp":
			contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
		case "Fuzzy":
			contains = fuzzyMatch(display, text)
		default:
			contains = strings.Contains(strings.ToLower(display), strings.ToLower(text))
		}
		if term.Negative {
			if contains {
				return false
			}
		} else {
			if !contains {
				return false
			}
		}
	}
	return true
}

func fuzzyMatch(s, pattern string) bool {
	sLow := strings.ToLower(s)
	pLow := strings.ToLower(pattern)
	j := 0
	for i := 0; i < len(sLow) && j < len(pLow); i++ {
		if sLow[i] == pLow[j] {
			j++
		}
	}
	return j == len(pLow)
}

func attemptScreenInit() {
	term := os.Getenv("TERM")
	if term == "" {
		fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set\n")
		os.Exit(1)
	}
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: failed to initialize tcell screen: open /dev/tty: no such device or address\n")
		os.Exit(1)
	}
	f.Close()
}

