func parseHeight(s string) error {
	if s == "" {
		return nil
	}
	if strings.HasSuffix(s, "%") {
		numStr := strings.TrimSuffix(s, "%")
		n, err := strconv.Atoi(numStr)
		if err != nil {
			return err
		}
		if n <= 0 || n > 100 {
			return fmt.Errorf("invalid")
		}
		return nil
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return err
	}
	if n < 0 {
		return fmt.Errorf("invalid")
	}
	return nil
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	if (fi.Mode() & os.ModeCharDevice) != 0 {
		return true
	}
	return false
}

func parseArgs(args []string) (*Config, error) {
	cfg := &Config{}
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			if cfg.File == "" {
				cfg.File = "--"
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			nameVal := strings.SplitN(arg[2:], "=", 2)
			name := nameVal[0]
			var val *string
			if len(nameVal) == 2 {
				v := nameVal[1]
				val = &v
			}
			switch name {
			case "help":
				cfg.Help = true
				i++
				continue
			case "version":
				cfg.Version = true
				i++
				continue
			case "null":
				cfg.Null = true
				i++
				continue
			case "select-1":
				cfg.Select1 = true
				i++
				continue
			case "exit-0":
				cfg.Exit0 = true
				i++
				continue
			case "select-all":
				cfg.SelectAll = true
				i++
				continue
			case "print-query":
				cfg.PrintQuery = true
				i++
				continue
			case "ansi":
				cfg.Ansi = true
				i++
				continue
			case "query":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--query")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Query = v
				i++
				continue
			case "rcfile":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--rcfile")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Rcfile = v
				i++
				continue
			case "buffer-size", "b":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--buffer-size")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					printInvalidIntArg("-b, --buffer-size", v)
					return nil, fmt.Errorf("invalid int")
				}
				cfg.BufferSize = &n
				i++
				continue
			case "initial-index":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--initial-index")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					printInvalidIntArg("--initial-index", v)
					return nil, fmt.Errorf("invalid int")
				}
				cfg.InitialIndex = &n
				i++
				continue
			case "initial-filter":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--initial-filter")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.InitialFilter = v
				i++
				continue
			case "prompt":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--prompt")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Prompt = v
				i++
				continue
			case "layout":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--layout")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Layout = v
				i++
				continue
			case "on-cancel":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--on-cancel")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.OnCancel = v
				i++
				continue
			case "selection-prefix":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--selection-prefix")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.SelectionPrefix = v
				i++
				continue
			case "exec":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--exec")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Exec = v
				i++
				continue
			case "height":
				var v string
				if val != nil {
					v = *val
				} else {
					if i+1 >= len(args) {
						printMissingArg("--height")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				cfg.Height = v
				i++
				continue
			default:
				fmt.Fprintf(os.Stderr, "unknown flag `%s'\n\n", name)
				fmt.Fprint(os.Stderr, usage)
				fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: unknown flag `%s'\n", name)
				return nil, fmt.Errorf("unknown")
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			if arg == "-h" {
				cfg.Help = true
				i++
				continue
			}
			if strings.HasPrefix(arg, "-b") {
				var v string
				rest := arg[2:]
				if rest != "" {
					if strings.HasPrefix(rest, "=") {
						v = rest[1:]
					} else {
						v = rest
					}
				} else {
					if i+1 >= len(args) {
						printMissingArg("-b, --buffer-size")
						return nil, fmt.Errorf("missing")
					}
					v = args[i+1]
					i++
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					printInvalidIntArg("-b, --buffer-size", v)
					return nil, fmt.Errorf("invalid int")
				}
				cfg.BufferSize = &n
				i++
				continue
			}
			flagName := strings.TrimLeft(arg, "-")
			fmt.Fprintf(os.Stderr, "unknown flag `%s'\n\n", flagName)
			fmt.Fprint(os.Stderr, usage)
			fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: unknown flag `%s'\n", flagName)
			return nil, fmt.Errorf("unknown")
		} else {
			if cfg.File == "" {
				cfg.File = arg
			}
			i++
			continue
		}
	}
	return cfg, nil
}

func printMissingArg(flag string) {
	fmt.Fprintf(os.Stderr, "expected argument for flag `%s'\n\n", flag)
	fmt.Fprint(os.Stderr, usage)
	fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: expected argument for flag `%s'\n", flag)
}

func printInvalidIntArg(flag, val string) {
	fmt.Fprintf(os.Stderr, "invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax\n\n", flag, val)
	fmt.Fprint(os.Stderr, usage)
	fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax\n", flag, val)
}
